from azure.servicebus import ServiceBusClient, ServiceBusMessage


def batch_publish(payloads, config=None):
    config = config or {}
    message_ids = []
    with ServiceBusClient.from_connection_string(config['connection_string']) as client:
        with client.get_topic_sender(topic_name=config['topic']) as sender:
            for payload in payloads:
                message_id = str(uuid.uuid4())
                sender.send_messages(ServiceBusMessage(json.dumps(payload['event']),
                    message_id=message_id, content_type='application/json'))
                message_ids.append(message_id)
    return {'message_ids': message_ids}

import json


def normalize_payload(payload):
    return json.dumps(payload)


def parse_response(response):
    return json.loads(response)

def summarize_message_processing(results):
    total_messages = len(results)
    success_count = sum(1 for result in results if result['status'] == 'success')
    failure_count = total_messages - success_count
    return {'total_messages': total_messages, 'success_count': success_count, 'failure_count': failure_count}

import re


def check_message_safety(payload):
    unsafe_patterns = [r'<script>', r'<iframe>', r'<object>']
    for pattern in unsafe_patterns:
        if re.search(pattern, payload):
            return False
    return True
